def multi_account_balances(events):
    balances = {}
    def ensure(acct):
        if acct not in balances:
            balances[acct] = 0
    for event in events:
        if event[0] == "deposit":
            _, acct, amt = event
            ensure(acct)
            balances[acct] += amt
        elif event[0] == "withdraw":
            _, acct, amt = event
            ensure(acct)
            if balances[acct] >= amt:
                balances[acct] -= amt
        elif event[0] == "transfer":
            _, frm, to, amt = event
            ensure(frm)
            ensure(to)
            if balances[frm] >= amt:
                balances[frm] -= amt
                balances[to] += amt
    return balances

